/* AVA POST-CALL — owner alert formatter.
   RUN 11: the owner email is now an HTML call report on the CIRCULANT light
   shell, and the owner SMS is a five-line brief. Every field is guarded — a
   value absent from the payload is never invented. Compact metadata cells
   collapse to an em-dash; content blocks say EMPTY — NO RESULT out loud, so a
   silent block is never mistaken for "nothing happened". */

const EMPTY = 'EMPTY — NO RESULT';
const DASH = '—';

const c = $('Retell Webhook').item.json.body.call || {};
const b = $('Retell Webhook').item.json.body || {};
const s = $('Normalize').item.json;
const an = c.call_analysis || {};
const cad = an.custom_analysis_data || {};

const val = (v) => {
  if (v === null || v === undefined) return null;
  const t = (v + '').trim();
  return (t && t !== 'undefined' && t !== 'null') ? t : null;
};
const esc = (v) => String(v === null || v === undefined ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/* duration: the payload carries duration_ms directly; timestamps are the
   fallback. Neither present -> say so rather than printing 0m 0s. */
let secs = null;
if (typeof c.duration_ms === 'number' && c.duration_ms >= 0) secs = Math.round(c.duration_ms / 1000);
else if (c.end_timestamp && c.start_timestamp) secs = Math.round((c.end_timestamp - c.start_timestamp) / 1000);
const durationRaw = secs !== null ? (Math.floor(secs / 60) + 'm ' + (secs % 60) + 's') : null;

const numberRaw = val(c.from_number);
const outcomeRaw = [
  val(an.user_sentiment),
  (an.call_successful === true ? 'successful' : an.call_successful === false ? 'unsuccessful' : null),
  val(c.disconnection_reason)
].filter(Boolean).join(' · ') || null;

/* --- BOOKED (RUN 6.6-C, logic unchanged) --------------------------------- */
const tw = Array.isArray(c.transcript_with_tool_calls) ? c.transcript_with_tool_calls : [];
const results = new Map();
for (const e of tw) { if (e && e.role === 'tool_call_result') results.set(e.tool_call_id, e); }
const attempts = tw.filter(e => e && e.role === 'tool_call_invocation' && e.name === 'book_appointment');

let booked = 'no';
let apptId = null;
let apptWhen = null;
let note = 'no booking attempted';

if (attempts.length) {
  let sawResult = false;
  note = null;
  for (const a of attempts) {
    const r = results.get(a.tool_call_id);
    if (!r) continue;
    sawResult = true;
    let p = null;
    try { p = JSON.parse(r.content || ''); } catch (err) { p = null; }
    if (p && p.success === true) {
      booked = 'yes'; apptId = p.appointment_id || null;
      apptWhen = p.start_time_human || p.start_time || null; note = null; break;
    }
    if (p && p.success === false) { booked = 'no'; note = p.reason || p.error || 'booking declined'; }
    else { booked = 'unknown'; note = 'unreadable booking result'; }
  }
  if (!sawResult) { booked = 'unknown'; note = 'booking attempted, no tool result recorded'; }
}
if (!tw.length && Array.isArray(c.tool_calls)) {
  const tried = c.tool_calls.some(t => t && t.name === 'book_appointment');
  booked = tried ? 'unknown' : 'no';
  note = tried ? 'booking attempted, transcript unavailable' : 'no booking attempted';
}
if (cad.booked === true || cad.booked_appointment === true) { booked = 'yes'; note = null; }

/* --- STATUS (RUN 7-CODE) — owner alerts open status-led ------------------ */
let status = 'FOLLOW-UP';
if (booked === 'yes') status = 'BOOKED';
else if (an.in_voicemail === true) status = 'VOICEMAIL';
else if (secs !== null && secs < 20) status = 'MISSED';
else if (c.disconnection_reason === 'dial_no_answer' || c.disconnection_reason === 'dial_busy' || c.disconnection_reason === 'voicemail_reached') status = 'MISSED';

/* --- SPEAKER-LABELLED TRANSCRIPT ------------------------------------------
   transcript_object is the structured record. The flat transcript string is the
   fallback and is RELABELLED, never re-derived. Absent -> EMPTY, never
   reconstructed from the summary, because a summary is not a transcript. */
const label = (role) => {
  const r = ((role == null ? '' : role) + '').toLowerCase();
  if (r === 'agent' || r === 'assistant') return 'AVA';
  if (r === 'user' || r === 'caller' || r === 'human') return 'CALLER';
  return r ? r.toUpperCase() : 'UNKNOWN';
};

let turns = [];
const tobj = Array.isArray(c.transcript_object) ? c.transcript_object : null;
if (tobj && tobj.length) {
  turns = tobj.map((e) => {
    const t = val(e && e.content);
    return t ? { who: label(e && e.role), text: t.replace(/\s+/g, ' ').trim() } : null;
  }).filter(Boolean);
}
if (!turns.length) {
  const flat = val(c.transcript);
  if (flat) {
    turns = flat.split('\n').map((ln) => {
      const m = ln.match(/^\s*(Agent|Assistant|User|Caller|Human)\s*:\s*(.*)$/i);
      if (m && val(m[2])) return { who: label(m[1]), text: m[2].trim() };
      const t = val(ln);
      return t ? { who: 'UNKNOWN', text: t } : null;
    }).filter(Boolean);
  }
}
const transcriptText = turns.length
  ? turns.map((t) => (t.who === 'AVA' ? 'AGENT' : t.who) + ': ' + t.text).join('\n')
  : EMPTY;

/* --- shared values -------------------------------------------------------- */
const when = DateTime.now().setZone('America/Chicago').toFormat('LLL d, yyyy · h:mm a') + ' CT';
const callId = val(s.call_id || c.call_id);
const recording = val(c.recording_url);
const summaryFull = val(an.call_summary) ? an.call_summary.replace(/\s+/g, ' ').trim() : null;

let summaryShort = summaryFull;
if (summaryShort && summaryShort.length > 220) summaryShort = summaryShort.slice(0, 217) + '…';

const bookedLine = booked + (apptId ? ' · appt ' + apptId + (apptWhen ? ' · ' + apptWhen : '') : (note ? ' · ' + note : ''));
const title = status + ' · ' + (numberRaw || DASH) + ' · ' + (durationRaw || DASH) + ' · ' + when;

/* --- OWNER SMS -----------------------------------------------------------
   Exactly five lines. `booked` can legitimately be 'unknown' (an attempt whose
   tool result was unreadable) and is reported as-is — collapsing it to 'no'
   would invent an outcome. */
let smsSummary = summaryFull;
if (!smsSummary) smsSummary = EMPTY;
else if (smsSummary.length > 80) smsSummary = smsSummary.slice(0, 77).trimEnd() + '…';

const headline = (booked === 'yes') ? 'AVA CALL — BOOKED 🔥' : ('AVA CALL — ' + status);
const ownerSms = [
  headline,
  (numberRaw || EMPTY) + ' · ' + (durationRaw || EMPTY),
  'Booked: ' + booked,
  smsSummary,
  'Full report emailed.'
].join('\n');

/* --- OWNER EMAIL · CIRCULANT light shell ---------------------------------
   Table-based, 600px, all-inline CSS, zero images (so images-off is identical
   to images-on). Explicit bgcolor attributes alongside inline background so
   Gmail's dark-mode inversion keeps every text/surface pair legible. Sharp
   corners and no shadows per the flat-UI law. */
const PILL = { BOOKED: '#2EE6A8', MISSED: '#FF3B4E', VOICEMAIL: '#FFB020', 'FOLLOW-UP': '#FFB020' };
const pillBg = PILL[status] || '#8A93A6';

const F = "'Space Grotesk','Helvetica Neue',Helvetica,Arial,sans-serif";
const INK = '#14161C';
const MUTED = '#5C6573';
const ACCENT = '#0090C8';
const LINE = '#DDE3EA';
/* deeper shade of the same hue: #0090C8 on the AVA row tint measures 3.23:1 and
   fails AA at label size. #00688F on #EAF4FA measures 5.57:1. */
const ACCENT_DEEP = '#00688F';

const row = (k, v, isLast) => {
  const bd = isLast ? '' : 'border-bottom:1px solid ' + LINE + ';';
  return '<tr>'
    + '<td width="34%" style="' + bd + 'padding:13px 0;font-family:' + F + ';font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:' + MUTED + ';font-weight:700;">' + esc(k) + '</td>'
    + '<td align="right" style="' + bd + 'padding:13px 0;font-family:' + F + ';font-size:15px;color:' + INK + ';font-weight:600;">' + esc(v || DASH) + '</td>'
    + '</tr>';
};

const block = (heading, inner) =>
  '<tr><td style="padding:26px 32px 0;font-family:' + F + ';font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:' + MUTED + ';font-weight:700;">' + heading + '</td></tr>'
  + '<tr><td style="padding:10px 32px 0;">' + inner + '</td></tr>';

const summaryBlock = block('Summary',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#FFFFFF" style="background:#FFFFFF;border:1px solid ' + LINE + ';">'
  + '<tr><td style="padding:16px 18px;font-family:' + F + ';font-size:15px;line-height:1.6;color:' + (summaryFull ? INK : MUTED) + ';">'
  + esc(summaryFull || EMPTY) + '</td></tr></table>');

let transcriptInner;
if (turns.length) {
  transcriptInner = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid ' + LINE + ';">';
  for (const t of turns) {
    const isAva = t.who === 'AVA';
    const bg = isAva ? '#EAF4FA' : '#FFFFFF';
    const who = isAva ? ACCENT_DEEP : MUTED;
    transcriptInner += '<tr>'
      + '<td bgcolor="' + bg + '" style="background:' + bg + ';padding:14px 18px;border-bottom:1px solid ' + LINE + ';font-family:' + F + ';">'
      + '<div style="font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:' + who + ';font-weight:700;padding-bottom:5px;">' + esc(t.who) + '</div>'
      + '<div style="font-size:15px;line-height:1.6;color:' + INK + ';">' + esc(t.text) + '</div>'
      + '</td></tr>';
  }
  transcriptInner += '</table>';
} else {
  transcriptInner = '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#FFFFFF" style="background:#FFFFFF;border:1px solid ' + LINE + ';">'
    + '<tr><td style="padding:16px 18px;font-family:' + F + ';font-size:15px;color:' + MUTED + ';">' + EMPTY + '</td></tr></table>';
}

/* Buttons. A button is rendered only when it has a real destination — a link to
   nowhere is worse than no link. ChatDash uses $vars.CHATDASH_URL when set and
   falls back to the provider call log the payload already carries. */
const chatdashBase = val(typeof $vars !== 'undefined' ? $vars.CHATDASH_URL : null);
const chatdashUrl = chatdashBase
  ? (chatdashBase.replace(/\/+$/, '') + (callId ? '/' + encodeURIComponent(callId) : ''))
  : val(b.chatdash_url) || val(c.public_log_url);
const chatdashLabel = chatdashBase ? 'Open in ChatDash' : 'Open call log';

const btn = (href, text, solid) => {
  const bg = solid ? ACCENT : '#FFFFFF';
  const fg = INK;
  return '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="display:inline-block;margin:0 6px 10px 0;">'
    + '<tr><td bgcolor="' + bg + '" style="background:' + bg + ';border:1px solid ' + (solid ? ACCENT : LINE) + ';">'
    + '<a href="' + esc(href) + '" style="display:block;padding:14px 26px;font-family:' + F + ';font-size:15px;font-weight:700;color:' + fg + ';text-decoration:none;">' + esc(text) + '</a>'
    + '</td></tr></table>';
};

let buttons = '';
if (recording) buttons += btn(recording, 'Listen to Recording', true);
if (chatdashUrl) buttons += btn(chatdashUrl, chatdashLabel, false);
const buttonsRow = buttons
  ? '<tr><td style="padding:26px 32px 0;">' + buttons + '</td></tr>'
  : '<tr><td style="padding:26px 32px 0;font-family:' + F + ';font-size:13px;color:' + MUTED + ';">Recording: ' + EMPTY + '</td></tr>';

const html = '<!DOCTYPE html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head>'
  + '<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
  + '<meta http-equiv="X-UA-Compatible" content="IE=edge">'
  + '<meta name="x-apple-disable-message-reformatting">'
  /* light ONLY. Every text element below carries an explicit colour, so telling
     a client we also support dark would just invite it to paint un-styled text
     white on a white surface. This keeps clients that honour the hint from
     inverting; the ones that invert anyway (Gmail app) still land on dark
     surface + light text, which stays legible. */
  + '<meta name="color-scheme" content="light only"><meta name="supported-color-schemes" content="light only">'
  + '<title>' + esc(title) + '</title>'
  + '<style>:root{color-scheme:light only;supported-color-schemes:light only;}'
  + 'body{margin:0;padding:0;width:100%!important;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;}'
  + 'table{border-collapse:collapse;mso-table-lspace:0;mso-table-rspace:0;}a{text-decoration:none;}'
  + '@media only screen and (max-width:620px){.container{width:100%!important;}.px{padding-left:20px!important;padding-right:20px!important;}}'
  + '</style></head>'
  + '<body bgcolor="#F7F8FA" style="margin:0;padding:0;background:#F7F8FA;">'
  /* preheader: what the phone shows before opening */
  + '<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:#F7F8FA;opacity:0;">'
  + esc(status + ' · ' + (numberRaw || DASH) + ' · ' + (durationRaw || DASH) + ' · Booked: ' + booked)
  + '&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;</div>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#F7F8FA" style="background:#F7F8FA;">'
  + '<tr><td align="center" style="padding:24px 12px;">'
  + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" class="container" bgcolor="#FFFFFF" style="width:600px;max-width:600px;background:#FFFFFF;border:1px solid ' + LINE + ';">'

  /* header bar */
  + '<tr><td bgcolor="' + INK + '" style="background:' + INK + ';padding:18px 32px;font-family:' + F + ';font-size:14px;font-weight:700;letter-spacing:.14em;color:#FFFFFF;">'
  + 'AVA ' + DASH + ' CALL REPORT</td></tr>'

  /* outcome pill */
  + '<tr><td class="px" style="padding:28px 32px 0;">'
  + '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>'
  + '<td bgcolor="' + pillBg + '" style="background:' + pillBg + ';padding:9px 20px;font-family:' + F + ';font-size:14px;font-weight:700;letter-spacing:.1em;color:#14161C;">'
  + esc(status) + '</td></tr></table></td></tr>'

  /* label / value rows */
  + '<tr><td class="px" style="padding:22px 32px 0;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">'
  + row('From', numberRaw)
  + row('Duration', durationRaw)
  + row('Date / Time', when)
  + row('Booked', bookedLine)
  + row('Outcome', outcomeRaw, true)
  + '</table></td></tr>'

  + summaryBlock
  + block('Transcript', transcriptInner)
  + buttonsRow

  /* footer */
  + '<tr><td class="px" style="padding:26px 32px 30px;border-top:1px solid ' + LINE + ';margin-top:20px;font-family:' + F + ';font-size:12px;line-height:1.6;color:' + MUTED + ';">'
  + 'Call ID: ' + esc(callId || EMPTY) + '<br>Internal operational alert · AI Voice Agency</td></tr>'

  + '</table></td></tr></table></body></html>';

/* plain-text part — kept so the alert stays readable if HTML is stripped */
const bodyText = 'Outcome: ' + (outcomeRaw || EMPTY)
  + '\nBooked: ' + bookedLine
  + '\nSummary: ' + (summaryShort || EMPTY)
  + '\nRecording: ' + (recording || EMPTY)
  + '\nCall ID: ' + (callId || EMPTY)
  + '\n\n----- TRANSCRIPT -----\n' + transcriptText;

return [{ json: {
  log_title: title,
  log_html: html,
  log_body: bodyText,
  log_status: status,
  booked: booked,
  appointment_id: apptId,
  appointment_when: apptWhen,
  owner_sms: ownerSms,
  transcript_lines: turns.length
} }];

// RUN 1.7 — build the GHL upsert body HERE, not in an inline expression.
// Retell can deliver call_analyzed with an entirely empty custom_analysis_data
// (caller hangs up during the greeting). caller_phone is then '', the body goes
// out with no phone and no email, and GHL /contacts/upsert answers
// 400 "Pass at least one of number, email query parameter".
// The telephony ANI (call.from_number) is in the same payload — use it.
const s = $('Normalize').first().json;
const c = $('Retell Webhook').first().json.body.call || {};

const CHAUFFEUR = 'agent_8e9e7d477949c6babcbdcc756d';
// RUN 6.5 — OUR OWN numbers come from config (every Retell line, the published
// SMS line, both owner cells). A call from one of them is never a lead.
const OUR_NUMBERS = String($vars.OUR_NUMBERS || '').split(',').map((x) => ((x == null ? '' : x) + '').replace(/[^0-9]/g, '').slice(-10)).filter((x) => x.length === 10);

const toE164 = (raw) => {
  const d = ((raw == null ? '' : raw) + '').replace(/[^0-9]/g, '');
  if (d.length < 10) return '';
  const last10 = d.slice(-10);
  if (new Set(last10.split('')).size === 1) return ''; // 0000000000 etc
  if (OUR_NUMBERS.indexOf(last10) !== -1) return '';
  return d.length === 10 ? ('+1' + d) : ('+' + d);
};

const spoken = toE164(s.phone);
const ani    = toE164(c.from_number);
const phone  = spoken || ani;
const email  = ((s.email == null ? '' : s.email) + '').trim();
const isChauffeur = s.agent_id === CHAUFFEUR;

const tags = [isChauffeur ? 'aichauffeur-lead' : 'ava-demo-hot'];
// RUN 3 QUARANTINE - a synthetic write is legible as synthetic in the CRM
// itself, not only in the logs, so nobody works it as a real lead.
const q = $('Quarantine Gate').first().json;
if (q && q.is_test) { tags.push('TEST'); tags.push('zz-internal'); }
if (!spoken && ani) tags.push('phone-from-ani');
if (!phone) tags.push('phone-unresolved');

// RUN 6 - NAME HYGIENE. Retell hands us whatever the caller said plus whatever
// the analyser appended, e.g. "Robert - Owner" with an em dash. That reached GHL
// unsanitised; GHL then splits the string on the first space, so the CRM stored
// firstName "Robert" / lastName "\uFFFD Owner" - a replacement character sitting
// in a customer record. Strip the junk BEFORE the upsert, not after.
const cleanName = (v) => ((v == null ? '' : v) + '')
  .replace(/[\uFFFD]/g, ' ')            // U+FFFD replacement char (the actual bug)
  .replace(/[\u2013\u2014\u00B7|]/g, ' ') // en/em dash, middot, pipe -> space
  .replace(/[^\x20-\x7E]/g, '')         // anything else outside printable ASCII
  .replace(/\s+/g, ' ')
  .trim();

const body = {
  locationId: 'sdShCZCaxce8DHKbYcIl',
  firstName: cleanName(s.first_name) || 'Unknown Caller',
  source: isChauffeur ? 'AI Chauffeur Demo Call' : 'AVA Inbound Demo Call',
  tags: tags
};
if (phone) body.phone = phone;
if (email) body.email = email;
if (s.company) body.companyName = s.company;

// RUN 6.5 — an internal test call still needs a destination, so it reports an
// identifier and is routed to the zz-test contact instead of upserting a lead.
const isInternal = OUR_NUMBERS.indexOf(((c.from_number == null ? '' : c.from_number) + '').replace(/[^0-9]/g, '').slice(-10)) !== -1;
return [{ json: { ghl_body: body, is_internal: isInternal, has_identifier: !!(phone || email) || isInternal } }];

const CHAUFFEUR_AGENT = 'agent_8e9e7d477949c6babcbdcc756d';

const wh = ($('Retell Webhook').first().json || {}).body || {};
const call = wh.call || {};
const ca = call.call_analysis || {};
const cad = ca.custom_analysis_data || {};
const nz = $('Normalize').first().json || {};
const cr = $('Contact Ref').first().json || {};

let should_send = true;
let skip_reason = '';
const stop = (r) => { if (should_send) { should_send = false; skip_reason = r; } };

const contact_id = cr.contact_id || '';
if (!contact_id) stop('no GHL contact id on this call');
if (cr.is_internal === true || String(cr.is_internal) === 'true') stop('internal number, suppressed by the owner rail');

let dur_ms = Number(call.duration_ms || 0);
if (!dur_ms && call.end_timestamp && call.start_timestamp) dur_ms = Number(call.end_timestamp) - Number(call.start_timestamp);
if (dur_ms > 0 && dur_ms < 10000) stop('call ran ' + Math.round(dur_ms / 1000) + 's, under the 10s floor');

const dir = String(call.direction || '').toLowerCase();
if (dir && dir !== 'inbound') stop('direction is ' + dir + ', text-back is inbound only');

const dispo = String(cad.disposition || '') + ' ' + String(cad.spam || '') + ' ' + String(ca.call_summary || '');
if (cad.spam === true || String(cad.spam) === 'true') stop('spam flag on the call analysis');
if (call.in_voicemail === true || String(call.in_voicemail) === 'true') stop('call reached voicemail');
if (/\b(spam|robocall|telemarket|wrong number)\b/i.test(dispo)) stop('spam disposition in the call analysis');

const isChauffeur = String(nz.agent_id || '') === CHAUFFEUR_AGENT;

const qrows = [];
try {
  const all = $('Load Quote For SMS').all();
  for (let i = 0; i < all.length; i++) {
    const j = all[i].json || {};
    if (j && j.quote_id) qrows.push(j);
  }
} catch (e) { /* no quote node output */ }

const q = qrows.length ? qrows[0] : null;
const qStatus = q ? String(q.status || '') : '';
const hasQuote = !!(q && qStatus === 'QUOTED' && Number(q.all_in_total) > 0);

let vehicle = '';
let basis = '';
if (q) {
  try {
    const bd = JSON.parse(String(q.breakdown || '[]'));
    if (Array.isArray(bd) && bd.length) {
      vehicle = String(bd[0].label || '').replace(/ - (airport transfer|hourly)$/, '');
      basis = String(bd[0].detail || '');
    }
  } catch (e) { /* leave blank */ }
}

const STATUS_LINE = {
  QUOTED: 'Dispatch will confirm the details with you.',
  NO_ROUTE_FOUND: 'Dispatch will confirm the price for that route.',
  HUMAN_REVIEW_REQUIRED: 'Dispatch is setting the rate and will confirm it with you.',
  CORPORATE_RATE_REQUIRED: 'Your account is on contract pricing; dispatch will confirm that rate.',
  CAPTURE_ONLY: 'Dispatch will confirm the rate with you.'
};

let message = '';

if (isChauffeur && hasQuote) {
  const statusLine = STATUS_LINE[qStatus] || 'Dispatch will confirm the details with you.';
  message = 'AI Chauffeur — your quote: ' + vehicle + ', ' + basis + '. '
          + 'Gratuity & service included. All-in $' + Number(q.all_in_total) + '. '
          + statusLine + ' — AI Chauffeur Dispatch. Reply STOP to opt out.';
} else if (isChauffeur) {
  const statusLine = (q && STATUS_LINE[qStatus]) ? STATUS_LINE[qStatus] : 'Dispatch will confirm your rate shortly.';
  message = 'AI Chauffeur — thanks for calling. We have your trip details. '
          + statusLine + ' Call us back any time. — AI Chauffeur Dispatch. Reply STOP to opt out.';
} else {
  message = 'AVA here from AI Voice Agency — thanks for calling. '
          + '$497/mo, done-for-you, answers every call 24/7. '
          + 'Book a walkthrough: book.aivoiceagency.ai — AVA Team. Reply STOP to opt out.';
}

return [{
  json: {
    should_send: should_send,
    skip_reason: skip_reason,
    line: isChauffeur ? 'chauffeur' : 'ava',
    contact_id: contact_id,
    message: message,
    has_quote: hasQuote,
    quote_id: q ? String(q.quote_id) : '',
    quote_status: qStatus,
    quote_total: q ? Number(q.all_in_total) : null,
    vehicle: vehicle,
    basis: basis,
    duration_ms: dur_ms,
    direction: dir || 'unknown',
    call_id: nz.call_id || ''
  }
}];

const src = $('Format Call Log').first().json || {};

const F = "'Space Grotesk','Helvetica Neue',Helvetica,Arial,sans-serif";
const INK = '#14161C';
const MUTED = '#5C6573';
const LINE = '#DDE3EA';
const ACCENT_DEEP = '#00688F';
const EMPTY = 'EMPTY — NO RESULT';

const esc = (v) => String(v === undefined || v === null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const block = (heading, inner) =>
  '<tr><td style="padding:26px 32px 0;font-family:' + F + ';font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:' + MUTED + ';font-weight:700;">' + heading + '</td></tr>' +
  '<tr><td style="padding:10px 32px 0;">' + inner + '</td></tr>';

const rows = [];
try {
  const all = $('Load Quote For Owner').all();
  for (let i = 0; i < all.length; i++) {
    const j = all[i].json || {};
    if (j && j.quote_id) rows.push(j);
  }
} catch (e) { /* no quote */ }

const q = rows.length ? rows[0] : null;

const shell = (innerRows) =>
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" bgcolor="#FFFFFF" ' +
  'style="width:100%;background:#FFFFFF;border:1px solid ' + LINE + ';border-collapse:collapse;">' + innerRows + '</table>';

const line = (k, v, bold, isLast) =>
  '<tr>' +
  '<td style="padding:14px 18px;font-family:' + F + ';font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:' + MUTED + ';font-weight:700;' + (isLast ? '' : 'border-bottom:1px solid ' + LINE + ';') + '">' + esc(k) + '</td>' +
  '<td align="right" style="padding:14px 18px;font-family:' + F + ';font-size:' + (bold ? '18px' : '15px') + ';color:' + (bold ? ACCENT_DEEP : INK) + ';font-weight:' + (bold ? '700' : '600') + ';' + (isLast ? '' : 'border-bottom:1px solid ' + LINE + ';') + '">' + esc(v) + '</td>' +
  '</tr>';

let quoteInner;
let quote_text;

if (!q) {
  quoteInner = shell('<tr><td style="padding:16px 18px;font-family:' + F + ';font-size:15px;line-height:1.6;color:' + MUTED + ';">No quote was generated on this call.</td></tr>');
  quote_text = 'Quote: none generated on this call.';
} else {
  const money = (n) => '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
  const status = String(q.status || EMPTY);
  const parts = [];
  const txt = [];

  let bd = [];
  try { const p = JSON.parse(String(q.breakdown || '[]')); if (Array.isArray(p)) bd = p; } catch (e) { bd = []; }

  let baseRow = null;
  let scRow = null;
  const addons = [];
  for (let i = 0; i < bd.length; i++) {
    const b = bd[i];
    const label = String(b.label || '');
    if (i === 0) baseRow = b;
    else if (/gratuity/i.test(label)) scRow = b;
    else addons.push(b);
  }

  if (baseRow) {
    parts.push(line('Base — ' + String(baseRow.label || ''), money(baseRow.amount), false, false));
    txt.push('Base (' + String(baseRow.label || '') + '): ' + money(baseRow.amount));
    if (baseRow.detail) {
      parts.push('<tr><td colspan="2" style="padding:0 18px 14px;font-family:' + F + ';font-size:13px;line-height:1.6;color:' + MUTED + ';border-bottom:1px solid ' + LINE + ';">' + esc(String(baseRow.detail)) + '</td></tr>');
      txt.push('  ' + String(baseRow.detail));
    }
    if (baseRow.billable_hours !== undefined) {
      parts.push(line('Billable hours', String(baseRow.billable_hours) + ' (requested ' + String(baseRow.requested_hours) + ', minimum ' + String(baseRow.minimum_hours) + ')', false, false));
      txt.push('Billable hours: ' + String(baseRow.billable_hours) + ' (requested ' + String(baseRow.requested_hours) + ', minimum ' + String(baseRow.minimum_hours) + ')');
    }
  }
  if (scRow) {
    parts.push(line(String(scRow.label || 'service charge'), money(scRow.amount), false, false));
    txt.push(String(scRow.label || 'service charge') + ': ' + money(scRow.amount));
  }
  for (let i = 0; i < addons.length; i++) {
    const a = addons[i];
    const lbl = String(a.label || '') + (a.detail ? ' (' + String(a.detail) + ')' : '');
    parts.push(line(lbl, money(a.amount), false, false));
    txt.push(lbl + ': ' + money(a.amount));
  }

  const total = (q.all_in_total === null || q.all_in_total === undefined || Number(q.all_in_total) === 0) ? null : Number(q.all_in_total);
  if (total !== null) {
    parts.push(line('All-in total', money(total), true, false));
    txt.push('ALL-IN TOTAL: ' + money(total));
  } else {
    parts.push(line('All-in total', 'no retail number — ' + status, false, false));
    txt.push('ALL-IN TOTAL: no retail number (' + status + ')');
  }

  parts.push(line('Status', status, false, false));
  parts.push(line('Quote ID', String(q.quote_id || EMPTY), false, true));
  txt.push('Status: ' + status);
  txt.push('Quote ID: ' + String(q.quote_id || EMPTY));

  quoteInner = shell(parts.join(''));
  quote_text = txt.join('\n');
}

const quoteBlock = block('Quote', quoteInner);

let html = String(src.log_html || '');
const anchor = '<tr><td style="padding:26px 32px 0;font-family:' + F + ';font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:' + MUTED + ';font-weight:700;">Transcript</td></tr>';
const idx = html.indexOf(anchor);
let injected = false;
if (idx >= 0) {
  html = html.slice(0, idx) + quoteBlock + html.slice(idx);
  injected = true;
} else {
  const fallback = html.lastIndexOf('</table>');
  if (fallback >= 0) { html = html.slice(0, fallback) + quoteBlock + html.slice(fallback); injected = true; }
}

return [{
  json: {
    log_title: src.log_title,
    log_html: html,
    log_body: String(src.log_body || '') + '\n\n----- QUOTE -----\n' + quote_text,
    log_status: src.log_status,
    booked: src.booked,
    appointment_id: src.appointment_id,
    appointment_when: src.appointment_when,
    owner_sms: src.owner_sms,
    transcript_lines: src.transcript_lines,
    quote_injected: injected,
    quote_present: !!q,
    quote_id: q ? String(q.quote_id) : ''
  }
}];

// AVA Post-Call · node "Quarantine Gate"
// RUN 3. THE single place this workflow decides a call is synthetic.
//
// It sits directly after Normalize and BEFORE the fork to Build GHL Body /
// Format Call Log, so both the lead branch and the owner-alert branch inherit one
// decision. The owner-alert branch previously forked off Normalize and never passed
// through any internal check at all — a test call still paged the owner.
//
//   is_test = NANP-reserved 555 caller (spoken number or telephony ANI)
//          OR an explicit test_mode flag on the payload
//          OR the caller is one of OUR OWN lines (OUR_NUMBERS)
//
// A REAL person dialling the demo line from an unknown public number is NOT a test.
// They keep the full receipt — the receipt IS the demo. Only synthetic and internal
// traffic is quarantined.
const s = $('Normalize').first().json;
const body = $('Retell Webhook').first().json.body || {};
const c = body.call || {};

const d10 = (v) => String(v == null ? '' : v).replace(/[^0-9]/g, '').slice(-10);

const OUR = String(($vars && $vars.OUR_NUMBERS) || '')
  .split(',')
  .map((x) => d10(x))
  .filter((x) => x.length === 10);

const spoken = d10(s.phone);
const ani = d10(c.from_number);

const is555 = (n) => n.length === 10 && n.slice(0, 3) === '555';
const isOurs = (n) => n.length === 10 && OUR.indexOf(n) !== -1;

const is_555 = is555(spoken) || is555(ani);
const is_our_number = isOurs(spoken) || isOurs(ani);
const test_mode = (body.test_mode === true ||
                   String(body.test_mode).toLowerCase() === 'true' ||
                   (c.metadata && c.metadata.test_mode === true));

const is_test = !!(is_555 || test_mode || is_our_number);

let test_reason = '';
if (is_555) test_reason = 'caller is a NANP-reserved 555 test number';
else if (test_mode) test_reason = 'payload carried test_mode';
else if (is_our_number) test_reason = 'caller is one of OUR_NUMBERS';

// Pass the Normalize payload straight through so downstream nodes that read
// $json keep working unchanged; the quarantine fields ride alongside.
return [{
  json: Object.assign({}, s, {
    is_test: is_test,
    test_reason: test_reason,
    is_our_number: is_our_number,
    quarantine_note: is_test
      ? ('QUARANTINED — ' + test_reason + '; owner alert and text-back suppressed')
      : ''
  })
}];
